import{O as e,d as t,p as n}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as r}from"./app-U4R70jmM.js";var i=JSON.parse(`{"path":"/ai-eng/03-deep-learning-core/12-intro-to-jax.html","title":"JAX 入门","lang":"zh-CN","frontmatter":{},"git":{"createdTime":1787385595000,"updatedTime":1787488693000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":12.98,"words":3895},"filePathRelative":"ai-eng/03-deep-learning-core/12-intro-to-jax.md"}`),a={name:`12-intro-to-jax.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="jax-入门" tabindex="-1"><a class="header-anchor" href="#jax-入门"><span>JAX 入门</span></a></h1><blockquote><p>PyTorch 原地改张量,TensorFlow 构建计算图,JAX 编译纯函数。最后这一种,会改变你思考深度学习的方式。</p></blockquote><p><strong>类型:</strong> 动手构建<br><strong>编程语言:</strong> Python<br><strong>前置要求:</strong> 第 03 阶段第 01-10 课,基础 NumPy<br><strong>预计耗时:</strong> 约 90 分钟</p><h2 id="学习目标" tabindex="-1"><a class="header-anchor" href="#学习目标"><span>学习目标</span></a></h2><ul><li>用 JAX 的函数式 API(jax.numpy、jax.grad、jax.jit、jax.vmap)编写纯函数风格的神经网络代码</li><li>解释 PyTorch 的即时可变执行与 JAX 的函数式编译模型之间的关键设计差异</li><li>应用 jit 编译和 vmap 向量化,让训练循环相比朴素 Python 大幅提速</li><li>在 JAX 中训练一个简单网络,并对比其显式状态管理与 PyTorch 面向对象方式的不同</li></ul><h2 id="问题" tabindex="-1"><a class="header-anchor" href="#问题"><span>问题</span></a></h2><p>你已经会用 PyTorch 搭神经网络了。定义一个 <code>nn.Module</code>,调 <code>.backward()</code>,优化器走一步。能用,百万人在用。</p><p>但 PyTorch 的 DNA 里刻着一个约束:它在 Python 里即时地、一次一个操作地追踪执行。每个 <code>tensor + tensor</code> 都是一次独立的内核启动,每个训练步都重新解释一遍同样的 Python 代码。平时没问题,直到你要在 2048 块 TPU 上训练一个 5400 亿参数的模型——这时候开销会要了你的命。</p><p>Google DeepMind 用 JAX 训练 Gemini,Anthropic 用 JAX 训练 Claude。这些不是小打小闹——它们是地球上最大规模的神经网络训练。它们选 JAX,是因为 JAX 把你的训练循环当作一个可编译的程序,而不是一串 Python 调用。</p><p>JAX 就是长了三种超能力的 NumPy:自动微分、JIT 编译到 XLA、自动向量化。你写一个处理单个样本的函数,JAX 给你一个能处理整个批次、能算梯度、能编译成机器码、能跨多设备运行的函数——原函数一行都不用改。</p><h2 id="概念" tabindex="-1"><a class="header-anchor" href="#概念"><span>概念</span></a></h2><h3 id="jax-哲学" tabindex="-1"><a class="header-anchor" href="#jax-哲学"><span>JAX 哲学</span></a></h3><p>JAX 是函数式框架。没有类,没有可变状态,没有 <code>.backward()</code> 方法。取而代之的是:</p><table><thead><tr><th>PyTorch</th><th>JAX</th></tr></thead><tbody><tr><td>带状态的 <code>nn.Module</code> 类</td><td>纯函数:<code>f(params, x) -&gt; y</code></td></tr><tr><td><code>loss.backward()</code></td><td><code>jax.grad(loss_fn)(params, x, y)</code></td></tr><tr><td>即时执行</td><td>经 XLA 的 JIT 编译</td></tr><tr><td><code>for x in batch:</code> 手写循环</td><td><code>jax.vmap(f)</code> 自动向量化</td></tr><tr><td><code>DataParallel</code> / <code>FSDP</code></td><td><code>jax.pmap(f)</code> 自动并行</td></tr><tr><td>可变的 <code>model.parameters()</code></td><td>不可变的数组 pytree</td></tr></tbody></table><p>这不是风格偏好,而是编译器的硬性约束。JIT 编译要求纯函数——同样的输入永远产出同样的输出,没有副作用。正是这个限制,让 100 倍加速成为可能。</p><h3 id="jax-numpy-熟悉的表面" tabindex="-1"><a class="header-anchor" href="#jax-numpy-熟悉的表面"><span>jax.numpy:熟悉的表面</span></a></h3><p>JAX 在加速器上重新实现了 NumPy API:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> jax.numpy </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> jnp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">a </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">([</span><span style="color:#D19A66;">1.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">3.0</span><span style="color:#ABB2BF;">])</span></span>
<span class="line"><span style="color:#ABB2BF;">b </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">([</span><span style="color:#D19A66;">4.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">5.0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">6.0</span><span style="color:#ABB2BF;">])</span></span>
<span class="line"><span style="color:#ABB2BF;">c </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(a, b)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>函数名一样,广播规则一样,切片语义一样。但数组活在 GPU/TPU 上,每个操作都能被编译器追踪。</p><p>一个关键区别:JAX 数组是不可变的。不能写 <code>a[0] = 5</code>,要写 <code>a = a.at[0].set(5)</code>。这会别扭一个星期,然后你就想通了——正是不可变性,让 <code>grad</code>、<code>jit</code>、<code>vmap</code> 这些变换可以任意组合。</p><h3 id="jax-grad-函数式自动微分" tabindex="-1"><a class="header-anchor" href="#jax-grad-函数式自动微分"><span>jax.grad:函数式自动微分</span></a></h3><p>PyTorch 把梯度挂在张量上(<code>.grad</code>),JAX 把梯度挂在函数上。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> jax</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> f</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> x </span><span style="color:#56B6C2;">**</span><span style="color:#D19A66;"> 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">df </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">grad</span><span style="color:#ABB2BF;">(f)</span></span>
<span class="line"><span style="color:#61AFEF;">df</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3.0</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>jax.grad</code> 接收一个函数,返回一个计算梯度的新函数。没有 <code>.backward()</code> 调用,张量上也不存计算图。梯度就是另一个你可以调用、组合、JIT 编译的函数。</p><p>组合可以任意深:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">d2f </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">grad</span><span style="color:#ABB2BF;">(jax.</span><span style="color:#61AFEF;">grad</span><span style="color:#ABB2BF;">(f))</span></span>
<span class="line"><span style="color:#61AFEF;">d2f</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3.0</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>二阶导、三阶导、Jacobian、Hessian——全靠组合 <code>grad</code>。PyTorch 也能做(<code>torch.autograd.functional.hessian</code>),但那是后来补上去的;在 JAX 里,这是地基。</p><p>约束是:<code>grad</code> 只作用于纯函数。函数里不能有 print(它只在追踪时执行,不在真正执行时)、不能改外部状态、不能用没有显式密钥管理的随机数。</p><h3 id="jit-编译到-xla" tabindex="-1"><a class="header-anchor" href="#jit-编译到-xla"><span>jit:编译到 XLA</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#61AFEF;">@jax</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">jit</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> train_step</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">y</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> loss_fn</span><span style="color:#ABB2BF;">(params, x, y)</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> loss</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">fast_step </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">jit</span><span style="color:#ABB2BF;">(train_step)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>第一次调用时,JAX 追踪这个函数——它记录发生了哪些操作,但不真正执行。然后它把这份追踪交给 XLA(Accelerated Linear Algebra),Google 为 TPU 和 GPU 打造的编译器。XLA 融合操作、消除冗余的内存拷贝、生成优化的机器码。</p><p>之后的调用完全跳过 Python,编译后的代码在加速器上以 C++ 的速度运行。</p><p>JIT 什么时候有用:</p><ul><li>训练步(同样的计算重复几千次)</li><li>推理(同一个模型,不同输入)</li><li>任何用相似形状的输入反复调用的函数</li></ul><p>JIT 什么时候帮倒忙:</p><ul><li>函数里有依赖数值的 Python 控制流(<code>if x &gt; 0</code>,而 x 是被追踪的数组)</li><li>只用一次的计算(编译开销超过运行时间)</li><li>调试(追踪掩盖了真实执行)</li></ul><p>控制流的限制是真的。<code>jax.lax.cond</code> 替代 <code>if/else</code>,<code>jax.lax.scan</code> 替代 <code>for</code> 循环。这不是可选项,而是编译的代价。</p><h3 id="vmap-自动向量化" tabindex="-1"><a class="header-anchor" href="#vmap-自动向量化"><span>vmap:自动向量化</span></a></h3><p>你写一个处理单个样本的函数:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> predict</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(params[</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">], x) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> params[</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>vmap</code> 把它提升为处理整个批次:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">batch_predict </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">vmap</span><span style="color:#ABB2BF;">(predict, </span><span style="color:#E06C75;font-style:italic;">in_axes</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">None</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>in_axes=(None, 0)</code> 的意思是:<code>params</code> 不做批处理(共享),<code>x</code> 沿第 0 轴做批处理。不用手写 <code>for</code> 循环,不用 reshape,不用手动穿批次维度。JAX 自己找出批次维度,把整个计算向量化。</p><p>这不是语法糖。<code>vmap</code> 生成的融合向量化代码比 Python 循环快 10-100 倍。而且它还能与 <code>jit</code> 和 <code>grad</code> 组合:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">per_example_grads </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">vmap</span><span style="color:#ABB2BF;">(jax.</span><span style="color:#61AFEF;">grad</span><span style="color:#ABB2BF;">(loss_fn), </span><span style="color:#E06C75;font-style:italic;">in_axes</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">None</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>逐样本梯度,一行搞定。在 PyTorch 里,不靠 hack 几乎做不到。</p><h3 id="pmap-跨设备数据并行" tabindex="-1"><a class="header-anchor" href="#pmap-跨设备数据并行"><span>pmap:跨设备数据并行</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">parallel_step </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">pmap</span><span style="color:#ABB2BF;">(train_step, </span><span style="color:#E06C75;font-style:italic;">axis_name</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;devices&#39;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>pmap</code> 把函数复制到所有可用设备(GPU/TPU)上,并切分批次。函数内部用 <code>jax.lax.pmean</code> 和 <code>jax.lax.psum</code> 跨设备同步梯度。</p><p>Google 用 <code>pmap</code>(及其后继 <code>shard_map</code>)在几千块 TPU v5e 芯片上训练 Gemini。编程模型是:写单设备版本,用 <code>pmap</code> 一包,完事。</p><h3 id="pytree-万能数据结构" tabindex="-1"><a class="header-anchor" href="#pytree-万能数据结构"><span>Pytree:万能数据结构</span></a></h3><p>JAX 操作的对象是 &quot;pytree&quot;——列表、元组、字典和数组的任意嵌套组合。你的模型参数就是一个 pytree:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">params </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#98C379;">    &#39;layer1&#39;</span><span style="color:#ABB2BF;">: {</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">((</span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">)), </span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">)},</span></span>
<span class="line"><span style="color:#98C379;">    &#39;layer2&#39;</span><span style="color:#ABB2BF;">: {</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">((</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">)), </span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">)},</span></span>
<span class="line"><span style="color:#98C379;">    &#39;layer3&#39;</span><span style="color:#ABB2BF;">: {</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">((</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)),  </span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)},</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每个 JAX 变换——<code>grad</code>、<code>jit</code>、<code>vmap</code>——都知道如何遍历 pytree。<code>jax.tree.map(f, tree)</code> 把 <code>f</code> 应用到每片叶子。优化器就是这样一次性更新所有参数的:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">params </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.tree.</span><span style="color:#61AFEF;">map</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">lambda</span><span style="color:#D19A66;font-style:italic;"> p</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">g</span><span style="color:#ABB2BF;">: p </span><span style="color:#56B6C2;">-</span><span style="color:#ABB2BF;"> lr </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> g, params, grads)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>没有 <code>.parameters()</code> 方法,没有参数注册。这棵树本身就是模型。</p><h3 id="函数式-vs-面向对象" tabindex="-1"><a class="header-anchor" href="#函数式-vs-面向对象"><span>函数式 vs 面向对象</span></a></h3><p>PyTorch 把状态存在对象里:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">class</span><span style="color:#E5C07B;"> Model</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">nn</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Module</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#56B6C2;"> __init__</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#E5C07B;">        self</span><span style="color:#ABB2BF;">.linear </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">Linear</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#61AFEF;"> forward</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">linear</span><span style="color:#ABB2BF;">(x)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JAX 用纯函数加显式状态:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> predict</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(x, params[</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">]) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> params[</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>参数是传进来的。什么都不存,什么都不改。这让每个函数都可测试、可组合、可编译。代价是参数要你自己管——或者用 Flax、Equinox 这样的库。</p><h3 id="jax-生态" tabindex="-1"><a class="header-anchor" href="#jax-生态"><span>JAX 生态</span></a></h3><p>JAX 给你原语,库给你易用性:</p><table><thead><tr><th>库</th><th>角色</th><th>风格</th></tr></thead><tbody><tr><td><strong>Flax</strong>(Google)</td><td>神经网络层</td><td>带显式状态的 <code>nn.Module</code></td></tr><tr><td><strong>Equinox</strong>(Patrick Kidger)</td><td>神经网络层</td><td>基于 pytree,Pythonic</td></tr><tr><td><strong>Optax</strong>(DeepMind)</td><td>优化器 + 学习率调度</td><td>可组合的梯度变换</td></tr><tr><td><strong>Orbax</strong>(Google)</td><td>检查点</td><td>保存/恢复 pytree</td></tr><tr><td><strong>CLU</strong>(Google)</td><td>指标 + 日志</td><td>训练循环工具</td></tr></tbody></table><p>Optax 是标准优化器库。它把梯度变换(Adam、SGD、裁剪)与参数更新解耦,组合起来易如反掌:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">optimizer </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optax.</span><span style="color:#61AFEF;">chain</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#ABB2BF;">    optax.</span><span style="color:#61AFEF;">clip_by_global_norm</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1.0</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    optax.</span><span style="color:#61AFEF;">adam</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">learning_rate</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1e-3</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="什么时候用-jax-什么时候用-pytorch" tabindex="-1"><a class="header-anchor" href="#什么时候用-jax-什么时候用-pytorch"><span>什么时候用 JAX,什么时候用 PyTorch</span></a></h3><table><thead><tr><th>因素</th><th>JAX</th><th>PyTorch</th></tr></thead><tbody><tr><td>TPU 支持</td><td>一等公民(Google 自产)</td><td>社区维护(torch_xla)</td></tr><tr><td>GPU 支持</td><td>好(经 XLA 走 CUDA)</td><td>最强(原生 CUDA)</td></tr><tr><td>调试</td><td>难(追踪 + 编译)</td><td>易(即时执行,逐行调试)</td></tr><tr><td>生态</td><td>研究导向(Flax、Equinox)</td><td>庞大(HuggingFace、torchvision 等)</td></tr><tr><td>招聘市场</td><td>小众(Google/DeepMind/Anthropic)</td><td>主流(到处都是)</td></tr><tr><td>大规模训练</td><td>更强(XLA、pmap、mesh)</td><td>好(FSDP、DeepSpeed)</td></tr><tr><td>原型速度</td><td>较慢(函数式开销)</td><td>较快(改了就能跑)</td></tr><tr><td>生产推理</td><td>TensorFlow Serving、Vertex AI</td><td>TorchServe、Triton、ONNX</td></tr><tr><td>谁在用</td><td>DeepMind(Gemini)、Anthropic(Claude)</td><td>Meta(Llama)、OpenAI(GPT)、Stability AI</td></tr></tbody></table><p>诚实的答案:除非你有具体理由,否则用 PyTorch。这些理由是——有 TPU 可用、需要逐样本梯度、超大规模多设备训练,或者你就在 Google/DeepMind/Anthropic 工作。</p><h3 id="jax-里的随机数" tabindex="-1"><a class="header-anchor" href="#jax-里的随机数"><span>JAX 里的随机数</span></a></h3><p>JAX 没有全局随机状态。每个随机操作都需要显式的 PRNG 密钥:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">key </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.random.</span><span style="color:#61AFEF;">PRNGKey</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">42</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">key1, key2 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.random.</span><span style="color:#61AFEF;">split</span><span style="color:#ABB2BF;">(key)</span></span>
<span class="line"><span style="color:#ABB2BF;">w </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.random.</span><span style="color:#61AFEF;">normal</span><span style="color:#ABB2BF;">(key1, </span><span style="color:#E06C75;font-style:italic;">shape</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一开始会很烦。但它保证了跨设备、跨编译的可复现性——这是 PyTorch 的 <code>torch.manual_seed</code> 在多 GPU 场景下保证不了的性质。</p><div class="language-figure line-numbers-mode" data-highlighter="shiki" data-ext="figure" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-figure"><span class="line"><span>batchnorm-effect</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="动手构建" tabindex="-1"><a class="header-anchor" href="#动手构建"><span>动手构建</span></a></h2><h3 id="第-1-步-环境与数据" tabindex="-1"><a class="header-anchor" href="#第-1-步-环境与数据"><span>第 1 步:环境与数据</span></a></h3><p>我们用 JAX 和 Optax 在 MNIST 上训练一个 3 层 MLP。784 个输入,两个隐藏层各 256 和 128 个神经元,10 个输出类别。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> jax</span></span>
<span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> jax.numpy </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> jnp</span></span>
<span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> jax </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> random</span></span>
<span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> optax</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> get_mnist_data</span><span style="color:#ABB2BF;">():</span></span>
<span class="line"><span style="color:#C678DD;">    from</span><span style="color:#ABB2BF;"> sklearn.datasets </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> fetch_openml</span></span>
<span class="line"><span style="color:#ABB2BF;">    mnist </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> fetch_openml</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;mnist_784&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">version</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">as_frame</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">False</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">parser</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&#39;auto&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    X </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> mnist.data.</span><span style="color:#61AFEF;">astype</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;float32&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">/</span><span style="color:#D19A66;"> 255.0</span></span>
<span class="line"><span style="color:#ABB2BF;">    y </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> mnist.target.</span><span style="color:#61AFEF;">astype</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;int&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    X_train, X_test </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> X[:</span><span style="color:#D19A66;">60000</span><span style="color:#ABB2BF;">], X[</span><span style="color:#D19A66;">60000</span><span style="color:#ABB2BF;">:]</span></span>
<span class="line"><span style="color:#ABB2BF;">    y_train, y_test </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> y[:</span><span style="color:#D19A66;">60000</span><span style="color:#ABB2BF;">], y[</span><span style="color:#D19A66;">60000</span><span style="color:#ABB2BF;">:]</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> X_train, y_train, X_test, y_test</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第-2-步-初始化参数" tabindex="-1"><a class="header-anchor" href="#第-2-步-初始化参数"><span>第 2 步:初始化参数</span></a></h3><p>没有类,只有一个返回 pytree 的函数:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> init_params</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">key</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    k1, k2, k3 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">split</span><span style="color:#ABB2BF;">(key, </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    scale1 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">sqrt</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2.0</span><span style="color:#56B6C2;"> /</span><span style="color:#D19A66;"> 784</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    scale2 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">sqrt</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2.0</span><span style="color:#56B6C2;"> /</span><span style="color:#D19A66;"> 256</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    scale3 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">sqrt</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2.0</span><span style="color:#56B6C2;"> /</span><span style="color:#D19A66;"> 128</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    params </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#98C379;">        &#39;layer1&#39;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;w&#39;</span><span style="color:#ABB2BF;">: scale1 </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">normal</span><span style="color:#ABB2BF;">(k1, (</span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#98C379;">            &#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        },</span></span>
<span class="line"><span style="color:#98C379;">        &#39;layer2&#39;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;w&#39;</span><span style="color:#ABB2BF;">: scale2 </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">normal</span><span style="color:#ABB2BF;">(k2, (</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#98C379;">            &#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        },</span></span>
<span class="line"><span style="color:#98C379;">        &#39;layer3&#39;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;w&#39;</span><span style="color:#ABB2BF;">: scale3 </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">normal</span><span style="color:#ABB2BF;">(k3, (</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)),</span></span>
<span class="line"><span style="color:#98C379;">            &#39;b&#39;</span><span style="color:#ABB2BF;">: jnp.</span><span style="color:#61AFEF;">zeros</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        },</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> params</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>手动做 He 初始化。三个 PRNG 密钥从一个种子分裂出来。每个权重都是嵌套字典里的一个不可变数组。</p><h3 id="第-3-步-前向传播" tabindex="-1"><a class="header-anchor" href="#第-3-步-前向传播"><span>第 3 步:前向传播</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> forward</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(x, params[</span><span style="color:#98C379;">&#39;layer1&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">]) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> params[</span><span style="color:#98C379;">&#39;layer1&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.nn.</span><span style="color:#61AFEF;">relu</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(x, params[</span><span style="color:#98C379;">&#39;layer2&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">]) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> params[</span><span style="color:#98C379;">&#39;layer2&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.nn.</span><span style="color:#61AFEF;">relu</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">    x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">dot</span><span style="color:#ABB2BF;">(x, params[</span><span style="color:#98C379;">&#39;layer3&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;w&#39;</span><span style="color:#ABB2BF;">]) </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> params[</span><span style="color:#98C379;">&#39;layer3&#39;</span><span style="color:#ABB2BF;">][</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> x</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> loss_fn</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">y</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    logits </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> forward</span><span style="color:#ABB2BF;">(params, x)</span></span>
<span class="line"><span style="color:#ABB2BF;">    one_hot </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.nn.</span><span style="color:#61AFEF;">one_hot</span><span style="color:#ABB2BF;">(y, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;">jnp.</span><span style="color:#61AFEF;">mean</span><span style="color:#ABB2BF;">(jnp.</span><span style="color:#61AFEF;">sum</span><span style="color:#ABB2BF;">(jax.nn.</span><span style="color:#61AFEF;">log_softmax</span><span style="color:#ABB2BF;">(logits) </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> one_hot, </span><span style="color:#E06C75;font-style:italic;">axis</span><span style="color:#56B6C2;">=-</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>纯函数。参数进,预测出。没有 <code>self</code>,不存状态。<code>loss_fn</code> 从零计算交叉熵——softmax、取 log、负均值。</p><h3 id="第-4-步-jit-编译的训练步" tabindex="-1"><a class="header-anchor" href="#第-4-步-jit-编译的训练步"><span>第 4 步:JIT 编译的训练步</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#61AFEF;">@jax</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">jit</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> train_step</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">opt_state</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">y</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    loss, grads </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jax.</span><span style="color:#61AFEF;">value_and_grad</span><span style="color:#ABB2BF;">(loss_fn)(params, x, y)</span></span>
<span class="line"><span style="color:#ABB2BF;">    updates, opt_state </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optimizer.</span><span style="color:#61AFEF;">update</span><span style="color:#ABB2BF;">(grads, opt_state, params)</span></span>
<span class="line"><span style="color:#ABB2BF;">    params </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optax.</span><span style="color:#61AFEF;">apply_updates</span><span style="color:#ABB2BF;">(params, updates)</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> params, opt_state, loss</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">@jax</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">jit</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> accuracy</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">params</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">y</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    logits </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> forward</span><span style="color:#ABB2BF;">(params, x)</span></span>
<span class="line"><span style="color:#ABB2BF;">    preds </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">argmax</span><span style="color:#ABB2BF;">(logits, </span><span style="color:#E06C75;font-style:italic;">axis</span><span style="color:#56B6C2;">=-</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">mean</span><span style="color:#ABB2BF;">(preds </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> y)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>jax.value_and_grad</code> 一次前向同时返回损失值和梯度。<code>@jax.jit</code> 装饰器把两个函数都编译到 XLA。第一次调用之后,每个训练步都不再经过 Python。</p><h3 id="第-5-步-训练循环" tabindex="-1"><a class="header-anchor" href="#第-5-步-训练循环"><span>第 5 步:训练循环</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">optimizer </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optax.</span><span style="color:#61AFEF;">adam</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">learning_rate</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1e-3</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">X_train, y_train, X_test, y_test </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> get_mnist_data</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">X_train, X_test </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">(X_train), jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">(X_test)</span></span>
<span class="line"><span style="color:#ABB2BF;">y_train, y_test </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">(y_train), jnp.</span><span style="color:#61AFEF;">array</span><span style="color:#ABB2BF;">(y_test)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">key </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">PRNGKey</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">params </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> init_params</span><span style="color:#ABB2BF;">(key)</span></span>
<span class="line"><span style="color:#ABB2BF;">opt_state </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optimizer.</span><span style="color:#61AFEF;">init</span><span style="color:#ABB2BF;">(params)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">batch_size </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 128</span></span>
<span class="line"><span style="color:#ABB2BF;">n_epochs </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> epoch </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(n_epochs):</span></span>
<span class="line"><span style="color:#ABB2BF;">    key, subkey </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">split</span><span style="color:#ABB2BF;">(key)</span></span>
<span class="line"><span style="color:#ABB2BF;">    perm </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> random.</span><span style="color:#61AFEF;">permutation</span><span style="color:#ABB2BF;">(subkey, </span><span style="color:#56B6C2;">len</span><span style="color:#ABB2BF;">(X_train))</span></span>
<span class="line"><span style="color:#ABB2BF;">    X_shuffled </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> X_train[perm]</span></span>
<span class="line"><span style="color:#ABB2BF;">    y_shuffled </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> y_train[perm]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">    epoch_loss </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0.0</span></span>
<span class="line"><span style="color:#ABB2BF;">    n_batches </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> len</span><span style="color:#ABB2BF;">(X_train) </span><span style="color:#56B6C2;">//</span><span style="color:#ABB2BF;"> batch_size</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> i </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(n_batches):</span></span>
<span class="line"><span style="color:#ABB2BF;">        start </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> i </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> batch_size</span></span>
<span class="line"><span style="color:#ABB2BF;">        xb </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> X_shuffled[start:start </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> batch_size]</span></span>
<span class="line"><span style="color:#ABB2BF;">        yb </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> y_shuffled[start:start </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> batch_size]</span></span>
<span class="line"><span style="color:#ABB2BF;">        params, opt_state, loss </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> train_step</span><span style="color:#ABB2BF;">(params, opt_state, xb, yb)</span></span>
<span class="line"><span style="color:#ABB2BF;">        epoch_loss </span><span style="color:#56B6C2;">+=</span><span style="color:#ABB2BF;"> loss</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">    train_acc </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> accuracy</span><span style="color:#ABB2BF;">(params, X_train[:</span><span style="color:#D19A66;">5000</span><span style="color:#ABB2BF;">], y_train[:</span><span style="color:#D19A66;">5000</span><span style="color:#ABB2BF;">])</span></span>
<span class="line"><span style="color:#ABB2BF;">    test_acc </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> accuracy</span><span style="color:#ABB2BF;">(params, X_test, y_test)</span></span>
<span class="line"><span style="color:#56B6C2;">    print</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Epoch </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">epoch </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;">:2d</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> | Loss: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">epoch_loss </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> n_batches</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> | &quot;</span></span>
<span class="line"><span style="color:#C678DD;">          f</span><span style="color:#98C379;">&quot;Train Acc: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">train_acc</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> | Test Acc: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">test_acc</span><span style="color:#C678DD;">:.4f</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>10 个 epoch,测试精度约 97%。第一个 epoch 慢(JIT 编译),第 2-10 个 epoch 快。</p><p>注意少了什么:没有 <code>.zero_grad()</code>,没有 <code>.backward()</code>,没有 <code>.step()</code>。整个更新就是一次组合好的函数调用。梯度被算出、经 Adam 变换、应用到参数上——全在 <code>train_step</code> 内部完成。</p><h2 id="投入使用" tabindex="-1"><a class="header-anchor" href="#投入使用"><span>投入使用</span></a></h2><h3 id="flax-google-标准" tabindex="-1"><a class="header-anchor" href="#flax-google-标准"><span>Flax:Google 标准</span></a></h3><p>Flax 是最常见的 JAX 神经网络库。它把 <code>nn.Module</code> 加了回来,但状态管理是显式的:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> flax.linen </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> nn</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">class</span><span style="color:#E5C07B;"> MLP</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">nn</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Module</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#61AFEF;">    @nn</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">compact</span></span>
<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#56B6C2;"> __call__</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">x</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">Dense</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">)(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">relu</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">Dense</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">)(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">relu</span><span style="color:#ABB2BF;">(x)</span></span>
<span class="line"><span style="color:#ABB2BF;">        x </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> nn.</span><span style="color:#61AFEF;">Dense</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)(x)</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#ABB2BF;"> x</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">model </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> MLP</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">params </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> model.</span><span style="color:#61AFEF;">init</span><span style="color:#ABB2BF;">(jax.random.</span><span style="color:#61AFEF;">PRNGKey</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">), jnp.</span><span style="color:#61AFEF;">ones</span><span style="color:#ABB2BF;">((</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">)))</span></span>
<span class="line"><span style="color:#ABB2BF;">logits </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> model.</span><span style="color:#61AFEF;">apply</span><span style="color:#ABB2BF;">(params, x_batch)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结构与 PyTorch 相同,但 <code>params</code> 与模型是分开的。<code>model.init()</code> 创建参数,<code>model.apply(params, x)</code> 跑前向。模型对象本身没有状态。</p><h3 id="equinox-pythonic-的替代者" tabindex="-1"><a class="header-anchor" href="#equinox-pythonic-的替代者"><span>Equinox:Pythonic 的替代者</span></a></h3><p>Equinox(Patrick Kidger 编写)把模型表示为 pytree:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> equinox </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> eqx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">model </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> eqx.nn.</span><span style="color:#61AFEF;">MLP</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    in_size</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">784</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">out_size</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">width_size</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">256</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">depth</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    activation</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">jax.nn.relu, </span><span style="color:#E06C75;font-style:italic;">key</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">jax.random.</span><span style="color:#61AFEF;">PRNGKey</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">logits </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> model</span><span style="color:#ABB2BF;">(x)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>模型本身就是 pytree,不需要 <code>.apply()</code>。参数就是模型的叶子。这更贴近 JAX 的思维方式。</p><h3 id="optax-可组合的优化器" tabindex="-1"><a class="header-anchor" href="#optax-可组合的优化器"><span>Optax:可组合的优化器</span></a></h3><p>Optax 把梯度变换与参数更新解耦:</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#ABB2BF;">schedule </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optax.</span><span style="color:#61AFEF;">warmup_cosine_decay_schedule</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    init_value</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">0.0</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">peak_value</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1e-3</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;font-style:italic;">    warmup_steps</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">decay_steps</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">50000</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">optimizer </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> optax.</span><span style="color:#61AFEF;">chain</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#ABB2BF;">    optax.</span><span style="color:#61AFEF;">clip_by_global_norm</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1.0</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    optax.</span><span style="color:#61AFEF;">adamw</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">learning_rate</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">schedule, </span><span style="color:#E06C75;font-style:italic;">weight_decay</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">0.01</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>梯度裁剪、学习率预热、权重衰减——全都组合成一条变换链。每个变换看到梯度、修改它、传给下一个。没有臃肿的一体化优化器类。</p><h2 id="交付" tabindex="-1"><a class="header-anchor" href="#交付"><span>交付</span></a></h2><p><strong>安装:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> jax</span><span style="color:#98C379;"> jaxlib</span><span style="color:#98C379;"> optax</span><span style="color:#98C379;"> flax</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>GPU 支持:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> jax[cuda12]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>TPU(Google Cloud):</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">pip</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> jax[tpu]</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> https://storage.googleapis.com/jax-releases/libtpu_releases.html</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>性能注意事项:</strong></p><ul><li>第一次 JIT 调用很慢(编译)。做基准测试前先热身。</li><li>JIT 内部避免对 JAX 数组写 Python 循环。用 <code>jax.lax.scan</code> 或 <code>jax.lax.fori_loop</code>。</li><li><code>jax.debug.print()</code> 在 JIT 里能用,普通 <code>print()</code> 不能。</li><li>用 <code>jax.profiler</code> 或 TensorBoard 做性能分析。XLA 编译可能掩盖瓶颈。</li><li>JAX 默认预分配 75% 的 GPU 显存。设 <code>XLA_PYTHON_CLIENT_PREALLOCATE=false</code> 可关闭。</li></ul><p><strong>检查点:</strong></p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> orbax.checkpoint </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> ocp</span></span>
<span class="line"><span style="color:#ABB2BF;">checkpointer </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> ocp.</span><span style="color:#61AFEF;">PyTreeCheckpointer</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">checkpointer.</span><span style="color:#61AFEF;">save</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/tmp/model&#39;</span><span style="color:#ABB2BF;">, params)</span></span>
<span class="line"><span style="color:#ABB2BF;">restored </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> checkpointer.</span><span style="color:#61AFEF;">restore</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;/tmp/model&#39;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>本课产出:</strong></p><ul><li><code>outputs/prompt-jax-optimizer.md</code> -- 一个选择合适 JAX 优化器配置的提示词</li><li><code>outputs/skill-jax-patterns.md</code> -- 一份涵盖 JAX 函数式模式的技能文档</li></ul><h2 id="练习" tabindex="-1"><a class="header-anchor" href="#练习"><span>练习</span></a></h2><ol><li><p>给 MLP 加 dropout。在 JAX 里,dropout 需要 PRNG 密钥——把一个密钥穿进前向传播,为每个 dropout 层分裂。对比有无 dropout 的测试精度。</p></li><li><p>用 <code>jax.vmap</code> 为一个 32 张 MNIST 图像的批次计算逐样本梯度。算出每个样本的梯度范数。哪些样本梯度最大,为什么?</p></li><li><p>把手写的 forward 函数换成通用的 <code>mlp_forward(params, x)</code>,支持任意层数。用 <code>jax.tree.leaves</code> 自动判断深度。</p></li><li><p>对比有无 <code>@jax.jit</code> 的训练步速度。各计时 100 步。在你的硬件上加速比多大?第一次调用的编译开销是多少?</p></li><li><p>用 <code>optax.chain(optax.clip_by_global_norm(1.0), optax.adam(1e-3))</code> 组合实现梯度裁剪。分别在有裁剪和无裁剪下训练。画出训练中的梯度范数曲线,观察效果。</p></li></ol><h2 id="关键术语" tabindex="-1"><a class="header-anchor" href="#关键术语"><span>关键术语</span></a></h2><table><thead><tr><th>术语</th><th>大家口头的说法</th><th>实际含义</th></tr></thead><tbody><tr><td>XLA</td><td>&quot;让 JAX 变快的东西&quot;</td><td>Accelerated Linear Algebra——一个编译器,从计算图出发融合操作、生成优化的 GPU/TPU 内核</td></tr><tr><td>JIT</td><td>&quot;即时编译&quot;</td><td>JAX 在第一次调用时追踪函数、编译到 XLA,之后的调用直接跑编译产物</td></tr><tr><td>纯函数</td><td>&quot;没有副作用&quot;</td><td>输出只取决于输入的函数——没有全局状态、没有原地修改、没有不带显式密钥的随机性</td></tr><tr><td>vmap</td><td>&quot;自动批处理&quot;</td><td>把处理单个样本的函数变换成处理整个批次的函数,无需改写</td></tr><tr><td>pmap</td><td>&quot;自动并行&quot;</td><td>把函数复制到多个设备上,并切分输入批次</td></tr><tr><td>Pytree</td><td>&quot;嵌套的数组字典&quot;</td><td>列表、元组、字典和数组的任意嵌套结构,JAX 可以遍历和变换它</td></tr><tr><td>追踪(Tracing)</td><td>&quot;记录计算过程&quot;</td><td>JAX 用抽象值执行函数以构建计算图,不算真实结果</td></tr><tr><td>函数式自动微分</td><td>&quot;对函数求导&quot;</td><td>通过变换函数来计算导数,而不是把梯度存储挂在张量上</td></tr><tr><td>Optax</td><td>&quot;JAX 的优化器库&quot;</td><td>可组合的梯度变换库——Adam、SGD、裁剪、调度——像链条一样串起来</td></tr><tr><td>Flax</td><td>&quot;JAX 的 nn.Module&quot;</td><td>Google 的 JAX 神经网络库,在保持状态显式的前提下加上层抽象</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读"><span>延伸阅读</span></a></h2><ul><li>JAX documentation: <a href="https://jax.readthedocs.io/" target="_blank" rel="noopener noreferrer">https://jax.readthedocs.io/</a> -- 官方文档,grad、jit、vmap 教程写得极好</li><li>&quot;JAX: composable transformations of Python+NumPy programs&quot; (Bradbury et al., 2018) -- 阐述设计哲学的原始论文</li><li>Flax documentation: <a href="https://flax.readthedocs.io/" target="_blank" rel="noopener noreferrer">https://flax.readthedocs.io/</a> -- Google 的 JAX 神经网络库</li><li>Patrick Kidger, &quot;Equinox: neural networks in JAX via callable PyTrees and filtered transformations&quot; (2021) -- Flax 之外更 Pythonic 的选择</li><li>DeepMind, &quot;Optax: composable gradient transformation and optimisation&quot; -- 标准优化器库</li><li>&quot;You Don&#39;t Know JAX&quot; (Colin Raffel, 2020) -- JAX 坑与模式的实战指南,作者来自 T5 团队</li></ul>`,125)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};